-- ============================================================================
-- REFRESH MEMOS — self-referencing lookups (see 02-create-functions.sql)
-- Generated by rulebook-to-postgres tool. Runs after the seed data. Each round
-- memoises the rows whose self-referenced parents are already memoised, so every
-- __compute call reads its parents from the memo. Rows on a genuine row cycle are
-- never ready and stay unmemoised (their wrapper falls back to __compute).
-- ============================================================================

CREATE OR REPLACE FUNCTION erb_refresh_memos() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM erb_memo_firings_rule_enabled;
  DELETE FROM erb_memo_statements_is_in_effect;
  DELETE FROM erb_memo_statements_count_of_inverse_firings;
  DELETE FROM erb_memo_statements_count_of_symmetric_firings;
  DELETE FROM erb_memo_statements_count_of_chain_firings;
  DELETE FROM erb_memo_statements_count_of_type_firings;
  DELETE FROM erb_memo_things_count_as_place;
  DELETE FROM erb_memo_things_count_of_children;
  DELETE FROM erb_memo_things_count_of_grandchildren;
  DELETE FROM erb_memo_things_count_as_subject;
  DELETE FROM erb_memo_things_count_as_object;
  DELETE FROM erb_memo_graphs_count_of_stated_facts;
  DELETE FROM erb_memo_graphs_count_of_conclusions;
  DELETE FROM erb_memo_graphs_count_of_violations;
  DELETE FROM erb_memo_graphs_count_of_facts_to_add;
  DELETE FROM erb_memo_graphs_next_fact_sort_order;
  DELETE FROM erb_memo_graphs_max_activation_seq;
  DELETE FROM erb_memo_graphs_max_listed_sort_order;
  DELETE FROM erb_memo_graphs_max_sort_order;
  INSERT INTO erb_memo_firings_rule_enabled(id, val) SELECT c.firing_id::text, calc_firings_rule_enabled__compute(c.firing_id) FROM firings c;
  INSERT INTO erb_memo_statements_is_in_effect(id, val) SELECT c.statement_id::text, calc_statements_is_in_effect__compute(c.statement_id) FROM statements c;
  INSERT INTO erb_memo_statements_count_of_inverse_firings(id, val) SELECT c.statement_id::text, calc_statements_count_of_inverse_firings__compute(c.statement_id) FROM statements c;
  INSERT INTO erb_memo_statements_count_of_symmetric_firings(id, val) SELECT c.statement_id::text, calc_statements_count_of_symmetric_firings__compute(c.statement_id) FROM statements c;
  INSERT INTO erb_memo_statements_count_of_chain_firings(id, val) SELECT c.statement_id::text, calc_statements_count_of_chain_firings__compute(c.statement_id) FROM statements c;
  INSERT INTO erb_memo_statements_count_of_type_firings(id, val) SELECT c.statement_id::text, calc_statements_count_of_type_firings__compute(c.statement_id) FROM statements c;
  INSERT INTO erb_memo_things_count_as_place(id, val) SELECT c.thing_id::text, calc_things_count_as_place__compute(c.thing_id) FROM things c;
  INSERT INTO erb_memo_things_count_of_children(id, val) SELECT c.thing_id::text, calc_things_count_of_children__compute(c.thing_id) FROM things c;
  INSERT INTO erb_memo_things_count_of_grandchildren(id, val) SELECT c.thing_id::text, calc_things_count_of_grandchildren__compute(c.thing_id) FROM things c;
  INSERT INTO erb_memo_things_count_as_subject(id, val) SELECT c.thing_id::text, calc_things_count_as_subject__compute(c.thing_id) FROM things c;
  INSERT INTO erb_memo_things_count_as_object(id, val) SELECT c.thing_id::text, calc_things_count_as_object__compute(c.thing_id) FROM things c;
  INSERT INTO erb_memo_graphs_count_of_stated_facts(id, val) SELECT c.graph_id::text, calc_graphs_count_of_stated_facts__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_count_of_conclusions(id, val) SELECT c.graph_id::text, calc_graphs_count_of_conclusions__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_count_of_violations(id, val) SELECT c.graph_id::text, calc_graphs_count_of_violations__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_count_of_facts_to_add(id, val) SELECT c.graph_id::text, calc_graphs_count_of_facts_to_add__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_next_fact_sort_order(id, val) SELECT c.graph_id::text, calc_graphs_next_fact_sort_order__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_max_activation_seq(id, val) SELECT c.graph_id::text, calc_graphs_max_activation_seq__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_max_listed_sort_order(id, val) SELECT c.graph_id::text, calc_graphs_max_listed_sort_order__compute(c.graph_id) FROM graphs c;
  INSERT INTO erb_memo_graphs_max_sort_order(id, val) SELECT c.graph_id::text, calc_graphs_max_sort_order__compute(c.graph_id) FROM graphs c;
END $$;

SELECT erb_refresh_memos();
